package com.example.marsthermal

/** Палитры (те же, что в Python-версии). Каждая — 256 цветов RRGGBB в строке. */
object Palettes {
    val NAMES = arrayOf("IRONBOW", "WHITE-HOT", "BLACK-HOT", "INFERNO", "MAGMA", "PLASMA", "TURBO", "JET", "HOT", "RAINBOW", "VIRIDIS", "CIVIDIS", "BONE")
    private val DATA = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    private val cache = HashMap<Int, IntArray>()

    /** 256 цветов ARGB для палитры idx; invert разворачивает палитру. */
    fun get(idx: Int, invert: Boolean): IntArray {
        val i = ((idx % NAMES.size) + NAMES.size) % NAMES.size
        val key = i * 2 + (if (invert) 1 else 0)
        return cache.getOrPut(key) {
            val s = DATA[i]
            val a = IntArray(256) { k -> 0xFF000000.toInt() or s.substring(k * 6, k * 6 + 6).toInt(16) }
            if (invert) a.reversedArray() else a
        }
    }
}
